INSERT INTO questions (id, level, topic_id, format, prompt, prompt_furigana, prompt_en, audio_url, explanation, difficulty, is_active) VALUES (1, 'N4', 2, 'multiple_choice', '「雨が降るかもしれませんから、傘を持っていきます。」', NULL, NULL, NULL, '〜かもしれません (might) correctly follows dictionary form 降る.', 1, 1);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (1, 1, 'True', 1, 0);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (2, 1, 'False', 0, 1);
INSERT INTO questions (id, level, topic_id, format, prompt, prompt_furigana, prompt_en, audio_url, explanation, difficulty, is_active) VALUES (2, 'N4', 2, 'multiple_choice', '「この料理はおいしいですが、高すぎません。」 (Intended: This food is delicious, but not too expensive.)', NULL, NULL, NULL, '〜すぎる does not naturally conjugate to 〜ません to express "not overly". Use それほど高くありません.', 1, 1);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (3, 2, 'False', 1, 0);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (4, 2, 'True', 0, 1);
INSERT INTO questions (id, level, topic_id, format, prompt, prompt_furigana, prompt_en, audio_url, explanation, difficulty, is_active) VALUES (3, 'N4', 2, 'multiple_choice', '「図書館で大きな声で話してはいけません。」', NULL, NULL, NULL, '〜てはいけません is standard for prohibition ("must not").', 1, 1);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (5, 3, 'True', 1, 0);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (6, 3, 'False', 0, 1);
INSERT INTO questions (id, level, topic_id, format, prompt, prompt_furigana, prompt_en, audio_url, explanation, difficulty, is_active) VALUES (4, 'N4', 2, 'multiple_choice', '「私は弟に宿題を手伝われました。」 (Intended: I helped my younger brother with his homework.)', NULL, NULL, NULL, 'Passive 手伝われました awkwardly means "I was helped by brother". Natural: 弟の宿題を手伝ってあげました.', 1, 1);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (7, 4, 'False', 1, 0);
INSERT INTO choices (id, question_id, body, is_correct, position) VALUES (8, 4, 'True', 0, 1);
